        );

        Ok(Self {
            conn,
            objects: HashMap::new(),
        })
    }

    pub async fn new_session() -> Result<Self> {
        let conn = Builder::session()?
            .name(op_plugins::canonical::BASE_SERVICE_NAME)?
            .build()
            .await?;

        info!(
            service = op_plugins::canonical::BASE_SERVICE_NAME,
