//! ⚖️ Identity-gated plugin mutations for the canonical D-Bus control plane.
//!
//! The caller supplies accountability metadata, while A.N.N.A. Scribe resolves
//! machine identity directly from The Sled at `/dev/shm/plugin_schema.dat`.

use anyhow::{bail, Context, Result};
use op_identity::{read_sled, IdentitySled, SHM_SLED_PATH};
use serde::Serialize;

pub const MUTATION_INTERFACE: &str = "org.opdbus.v1.plugins.Mutation";
pub const STATE_WRITE_CAPABILITY: &str = "cap:state-write";
pub const MUTATION_EVENT_SUBID: &str = "evt.service.state-sync.apply-patch@v1";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SledIdentity {
    pub actor_id: String,
    pub footprint: String,
    pub trace_id: String,
    pub mutation_index: u64,
    pub schema_version: u32,
}

#[derive(Debug, Serialize)]
pub struct MutationResponse {
    pub success: bool,
    pub plugin_id: String,
    pub actor_id: String,
    pub capability_id: String,
    pub subid: String,
    pub footprint: String,
    pub trace_id: String,
    pub mutation_index: u64,
    pub schema_version: u32,
    pub event_id: String,
    pub event_hash: String,
    pub event_subid: String,
    pub changes_applied: Vec<String>,
    pub errors: Vec<String>,
}

pub fn read_identity_sled() -> Result<SledIdentity> {
    let metadata = std::fs::metadata(SHM_SLED_PATH)
        .with_context(|| format!("A.N.N.A. Scribe cannot stat The Sled at {SHM_SLED_PATH}"))?;
    let expected = IdentitySled::SIZE as u64;
    if metadata.len() != expected {
        bail!(
            "The Sled layout is invalid: expected {expected} bytes, found {}",
            metadata.len()
        );
    }

    let (ptr, mmap) = read_sled()
        .with_context(|| format!("A.N.N.A. Scribe cannot read The Sled at {SHM_SLED_PATH}"))?;
    if mmap.len() != IdentitySled::SIZE {
        bail!("The Sled mapping changed while identity was being resolved");
    }

    // SAFETY: `read_sled` owns the read-only mapping guard returned alongside
    // the pointer, and both mapping lengths were checked against the canonical
    // `#[repr(C)] IdentitySled` size before this single snapshot clone.
    let sled = unsafe { (&*ptr).clone() };
    identity_from_sled(&sled)
}

fn identity_from_sled(sled: &IdentitySled) -> Result<SledIdentity> {
    if sled.schema_version == 0 {
        bail!("The Sled has no valid schema version");
    }
    if sled.wireguard_pubkey.iter().all(|byte| *byte == 0) {
        bail!("The Sled has no WireGuard identity");
    }
    if sled.hashed_footprint.iter().all(|byte| *byte == 0) {
        bail!("The Sled has no Strike/Etch footprint");
    }
    if sled.trace_id.iter().all(|byte| *byte == 0) {
        bail!("The Sled has no Snowball trace identity");
    }

    Ok(SledIdentity {
        actor_id: format!("wireguard:{}", hex::encode(sled.wireguard_pubkey)),
        footprint: hex::encode(sled.hashed_footprint),
        trace_id: hex::encode(sled.trace_id),
        mutation_index: sled.mutation_index,
        schema_version: sled.schema_version,
    })
}

pub fn validate_accountability(capability_id: &str, subid: &str) -> Result<()> {
    if capability_id != STATE_WRITE_CAPABILITY {
        bail!("capability_id is not authorized for plugin state mutation");
    }
    validate_mutation_subid(subid)
}

fn validate_mutation_subid(subid: &str) -> Result<()> {
    let (taxonomy, version) = subid
        .rsplit_once("@v")
        .context("subid must end in @vN")?;
    if version.is_empty() || !version.bytes().all(|byte| byte.is_ascii_digit()) {
        bail!("subid version must be numeric");
    }

    let parts = taxonomy.split('.').collect::<Vec<_>>();
    if !(4..=5).contains(&parts.len()) || parts[0] != "mut" {
        bail!("subid must use the mut category and canonical taxonomy shape");
    }

    const COMPONENT_TYPES: &[&str] = &[
        "software",
        "service",
        "network",
        "hardware",
        "process-procedure",
        "standard",
        "validation",
        "policy",
        "plan",
        "guidance",
        "physical",
        "this-system",
        "system",
        "interconnection",
    ];
    if !COMPONENT_TYPES.contains(&parts[1]) {
        bail!("subid has an invalid OSCAL component-type");
    }
    if parts.iter().any(|part| {
        part.is_empty()
            || !part
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
    }) {
        bail!("subid segments must be lowercase alphanumeric or hyphenated");
    }
    Ok(())
}

pub fn event_identity(
    identity: &SledIdentity,
    plugin_id: &str,
    capability_id: &str,
    subid: &str,
) -> (String, String) {
    let material = format!(
        "{}:{}:{}:{}:{}:{}",
        identity.actor_id,
        identity.footprint,
        identity.trace_id,
        plugin_id,
        capability_id,
        subid
    );
    let event_hash = blake3::hash(material.as_bytes()).to_hex().to_string();
    (format!("evt-{event_hash}"), event_hash)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid_sled() -> IdentitySled {
        IdentitySled {
            wireguard_pubkey: [1; 32],
            mutation_index: 7,
            hashed_footprint: [2; 32],
            trace_id: [3; 16],
            schema_version: 1,
            vector_id: [4; 16],
            reserved: [0; 44],
        }
    }

    #[test]
    fn should_derive_actor_from_wireguard_identity() {
        let identity = identity_from_sled(&valid_sled()).expect("valid identity");
        assert!(identity.actor_id.starts_with("wireguard:"));
        assert_eq!(identity.mutation_index, 7);
    }

    #[test]
    fn should_reject_identity_without_schema() {
        let mut sled = valid_sled();
        sled.schema_version = 0;
        assert!(identity_from_sled(&sled).is_err());
    }

    #[test]
    fn should_require_state_write_capability_and_mutation_subid() {
        assert!(validate_accountability(
            STATE_WRITE_CAPABILITY,
            "mut.service.s6.start-unit@v1"
        )
        .is_ok());
        assert!(validate_accountability("cap:read", "mut.service.s6.start-unit@v1").is_err());
        assert!(validate_accountability(STATE_WRITE_CAPABILITY, "obs.service.s6.status@v1")
            .is_err());
    }
}

